//! Status-line-sized worker activity summaries: rendered from the tool-call
//! stream mid-round, generated by a lightweight model at round boundaries.
//!
//! A background worker's `:workers` **Task** cell and the escalation banner's
//! task hint both have to answer "what is this worker actually doing?" in ONE
//! line of a real terminal. The durable `task` brief is the wrong text for that
//! job: it is the entire multi-paragraph assignment, so clipping it to the cell
//! width yields the first few words of the *preamble* and says nothing about
//! progress. Every worker in a fan-out that shares a preamble renders as the
//! same indistinguishable row.
//!
//! This module fixes that by maintaining a short, present-tense **activity
//! summary** at the three points in a worker's life where the answer changes:
//!
//! 1. **on worker start** — from the task brief, so the row is meaningful before
//!    the first round even finishes (one cheap model call, [`SUMMARY_MODEL`]);
//! 2. **mid-round, from the live tool-call stream** ([`ActivityTracker`]) —
//!    *rendered*, not generated: [`phrase`] + [`midround_summary`] are pure
//!    functions over the tool call the tracker already sees, throttled to
//!    [`MIDROUND_INTERVAL`]; and
//! 3. **at the end of every round** — from that round's synthesis, so the row
//!    tracks the work instead of freezing at the assignment (one model call).
//!
//! ## Why mid-round is deterministic
//!
//! Mid-round is the HOT path — it fires on tool-call completion, many times per
//! round, on every live worker. The input there is already structured (a tool
//! name plus `engine::describe_call`'s display description), and the output is
//! one glanceable line, so asking a model to turn `read_file` + `read
//! src/lib.rs` into "reading src/lib.rs" buys nothing an exhaustive match arm
//! cannot: it just adds a model call, a failure mode, and latency to the
//! worker's inner loop. So the two boundary refreshes — which summarize PROSE
//! (the brief, the synthesis) — still call a model, and the per-call path is a
//! pure format. That keeps the summarizer's cost O(rounds) instead of
//! O(tool calls) with no loss of signal.
//!
//! ## Why mid-round is the load-bearing one
//!
//! Points 1 and 3 alone are nearly useless in practice, and the reason is
//! visible in the run table: a coordinator does its ENTIRE job in **one round**.
//! Observed on live runs — `turns = 1` with 20–44 tool calls spanning 3–8
//! minutes of wall clock. With refreshes only at round boundaries, the end-of-
//! round refresh therefore fires exactly ONCE, as the run terminates, and for
//! the whole visible lifetime of the worker every surface shows the STARTUP
//! summary. When the brief is short enough that the startup pass can't name
//! anything concrete it emits the [`STARTUP_FALLBACK`] sentinel, which then
//! sticks — producing the reported symptom: a worker burning tool calls for
//! minutes while `:workers` and the escalation banner both read
//! `running · starting up`.
//!
//! [`ActivityTracker`] closes that gap by refreshing from the tool calls as they
//! complete, so the row tracks work at [`MIDROUND_INTERVAL`] granularity INSIDE
//! a round.
//!
//! The result is persisted on the run row (`coordinator_runs.activity_summary`)
//! and preferred over `task` by both consuming surfaces.
//!
//! ## Why the budget is derived, not guessed
//!
//! The whole point is to FIT, so the character allowance is computed from the
//! actual render chrome of the consuming surfaces rather than hardcoded to a
//! number that silently drifts away from the code:
//!
//! | surface | chrome | source |
//! |---|---|---|
//! | `:workers` row | [`WORKERS_ROW_CHROME`] | `workers_modal::render` |
//! | escalation head row | [`ESCALATION_HEAD_CHROME`] | `escalation::render` |
//! | escalation status row | [`ESCALATION_STATUS_CHROME`] | `escalation::render` |
//!
//! [`budget`] takes the NARROWEST of the three at the live terminal width — the
//! `:workers` row, which carries the most chrome — and clamps it to
//! [`MIN_BUDGET`]`..=`[`MAX_BUDGET`]. The upper clamp matters as much as the
//! lower one: past ~80 characters a status line stops being glanceable and turns
//! into prose, so a very wide terminal does not buy a rambling summary.
//!
//! Worked example on a 155-column terminal (the width this was tuned against):
//! `min(155-46, 155-26, 155-16) = 109`, clamped to **80**. On a classic 80-column
//! terminal: `min(34, 54, 64) = 34`. Both fit every surface with no mid-word
//! truncation at the render site.
//!
//! Everything decision-shaped here is a pure function with unit tests; the only
//! impure part is the single tool-less [`Backend::complete`] call in
//! [`summarize`], which the mid-round path does not use at all.

use crate::backend::{Backend, Msg};
use crate::session::Session;

/// The lightweight model the summarizer prefers. Summarizing one round of work
/// into ~80 characters is a shallow transform — paying frontier-model rates per
/// round for it (on EVERY live worker) is pure waste, so this pins the cheapest
/// capable Claude tier regardless of what the worker itself runs on.
pub const SUMMARY_MODEL: &str = "claude-haiku-4-5";

/// Fixed (non-task) width of a `:workers` modal row.
///
/// Mirrors the format string in `workers_modal::render`:
/// `{gutter:2}{emoji:2}  {id_w}  {st_w+2}  {rt_w}  {task}` — that is 2 (gutter)
/// plus 2 (type glyph) plus 4×2 (separators) plus the three data columns,
/// budgeted at their realistic maxima: id 13 (`w_z1EjHWKA` plus a `↻N` resumed
/// marker), status 12 (`coordinating`), runtime 7 (`1h02m`), giving
/// `12 + 13 + 12 + 7 = 44` — rounded to 46 for the two-space lead-in the header
/// reserves.
pub const WORKERS_ROW_CHROME: usize = 46;

/// Fixed width of the escalation banner's head row.
///
/// Mirrors `escalation::render`: `{glyph:2} {short:8} · ` — 2 glyph
/// + 1 space + 8 (`crate::batch::short_id`) + 3 (` · `) = 14.
///
/// The glyph is `escalation::LIVE_GLYPH` (`🚀`) while the coordinator works and
/// ✅/⚠️ once it finishes — all 2 columns, and all STATIC. The banner's motion
/// lives in the status row below (see [`ESCALATION_STATUS_CHROME`]), so nothing
/// on this row changes width mid-animation.
pub const ESCALATION_HEAD_CHROME: usize = 14;

/// Fixed width of the escalation banner's indented status row.
///
/// Mirrors `escalation::render`: `   {prefix} {elapsed} · ` — 3 indent
/// + 2 (prefix + space) + 8 (`1h02m12s` worst case) + 3 (` · `) = 16.
///
/// The prefix is a pulsing one-column liveness heart, or the static
/// `escalation::IDLE_PREFIX` elbow (`↳`) once finished. Missed beats may append
/// their age; both glyphs hold their width throughout the pulse.
pub const ESCALATION_STATUS_CHROME: usize = 16;

/// Floor for the summary budget. Below this a summary can't carry a verb plus an
/// artifact name, so a very narrow terminal accepts clipping at the render site
/// rather than degrading the summary itself into uselessness.
pub const MIN_BUDGET: usize = 28;

/// Ceiling for the summary budget. A status line longer than this is prose, not
/// a glance — an ultra-wide terminal does not earn a rambling row.
pub const MAX_BUDGET: usize = 80;

/// The character allowance for a summary at `term_width`, derived from the real
/// render chrome of every consuming surface and clamped to
/// [`MIN_BUDGET`]`..=`[`MAX_BUDGET`]. Pure.
///
/// Uses the narrowest surface so ONE stored string fits them all. `usize::MAX`
/// (what `md::term_width` returns for piped output) saturates to the ceiling
/// rather than overflowing.
pub fn budget(term_width: usize) -> usize {
    let narrowest = term_width
        .saturating_sub(WORKERS_ROW_CHROME)
        .min(term_width.saturating_sub(ESCALATION_HEAD_CHROME))
        .min(term_width.saturating_sub(ESCALATION_STATUS_CHROME));
    narrowest.clamp(MIN_BUDGET, MAX_BUDGET)
}

/// [`budget`] at the live terminal width.
pub fn current_budget() -> usize {
    budget(crate::md::term_width())
}

/// How much of the task brief to show the summarizer. The opening of a brief
/// carries the intent; the tail is usually boilerplate, and a cheap model does
/// not need the whole thing to name the work.
const TASK_CONTEXT_MAX: usize = 600;

/// How much of the latest round synthesis to show the summarizer. Generous
/// enough to capture what actually happened in the round.
const RECENT_CONTEXT_MAX: usize = 1200;

/// The sentinel the model emits when nothing concrete has happened yet, mapped
/// to a plain-English starting state rather than an empty cell.
const STARTUP_FALLBACK: &str = "starting up";

/// The summarizer's system prompt, budget-interpolated so the hard limit the
/// model is told matches the limit [`sanitize`] enforces. Pure.
pub fn summarizer_system(budget: usize) -> String {
    format!(
        "You write ONE ultra-short status line describing what a background agent worker is \
doing RIGHT NOW. It renders in a terminal status row, so it must fit.\n\n\
Rules:\n\
- Output ONLY the status line. No prose, no preamble, no quotes, no markdown, no code fences, \
no bullet, no trailing period.\n\
- HARD LIMIT: {budget} characters. Shorter is better — aim for {aim}.\n\
- Present tense, active voice, concrete. Lead with the verb: \"wiring summaries into :workers\", \
\"fixing CI on feat/foo\", \"auditing 12 merged cards\".\n\
- Name the specific artifact — file, module, branch, PR, test, card — whenever you know it.\n\
- Describe the CURRENT step, not the whole assignment.\n\
- No filler. Never \"working on\", \"currently\", \"the task is\", \"the agent is\", \
\"continuing to\".\n\
- If nothing concrete has happened yet, output exactly: {STARTUP_FALLBACK}",
        aim = budget.saturating_sub(budget / 4).max(MIN_BUDGET),
    )
}

/// Assemble the summarizer's user message: the assignment for grounding, then
/// the latest round synthesis when there is one. Pure + deterministic so the
/// prompt shape is unit-testable.
pub fn build_prompt(task: &str, recent: Option<&str>, budget: usize) -> String {
    let mut p = String::with_capacity(TASK_CONTEXT_MAX + RECENT_CONTEXT_MAX + 256);
    p.push_str("ASSIGNMENT (for context — do NOT just restate it):\n");
    p.push_str(&clip_chars(task.trim(), TASK_CONTEXT_MAX));
    match recent.map(str::trim).filter(|r| !r.is_empty()) {
        Some(r) => {
            p.push_str("\n\nMOST RECENT TURN (what just happened — summarize THIS):\n");
            p.push_str(&clip_chars(r, RECENT_CONTEXT_MAX));
            p.push_str("\n\nStatus line describing the worker's current step");
        }
        None => {
            p.push_str(
                "\n\nThe worker is just starting — no turns have completed yet.\n\n\
Status line describing what it is about to begin",
            );
        }
    }
    p.push_str(&format!(" (max {budget} chars):"));
    p
}

/// Turn the model's raw reply into one clean status line within `budget`, or
/// `None` when it returned nothing usable. Strips code fences, bullets, quotes,
/// and a trailing period; collapses whitespace; takes the first meaningful line;
/// then clips on a WORD boundary so a row never ends mid-identifier. Pure.
pub fn sanitize(raw: &str, budget: usize) -> Option<String> {
    let first = raw
        .lines()
        .map(str::trim)
        .find(|l| !l.is_empty() && !l.starts_with("```"))?;
    // Collapse internal whitespace — a status row is strictly one line.
    let mut s: String = first.split_whitespace().collect::<Vec<_>>().join(" ");
    // Strip a leading bullet/sigil the model may have added anyway.
    for p in ["- ", "* ", "• ", "> ", "$ "] {
        if let Some(rest) = s.strip_prefix(p) {
            s = rest.trim().to_string();
            break;
        }
    }
    // Strip symmetric wrapping quotes/backticks.
    for q in ['"', '\'', '`'] {
        if s.len() >= 2 && s.starts_with(q) && s.ends_with(q) {
            s = s[q.len_utf8()..s.len() - q.len_utf8()].trim().to_string();
        }
    }
    // A status line is a fragment, not a sentence — drop a trailing period.
    if let Some(rest) = s.strip_suffix('.')
        && !rest.ends_with('.')
    {
        s = rest.trim_end().to_string();
    }
    if s.is_empty() {
        return None;
    }
    Some(clip_words(&s, budget))
}

/// Clip to at most `max` characters on a word boundary, appending `…` when
/// anything was dropped. Falls back to a hard character clip when the first word
/// alone overruns the budget. Pure.
pub fn clip_words(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    // Reserve one cell for the ellipsis.
    let room = max.saturating_sub(1);
    let mut out = String::new();
    for word in s.split_whitespace() {
        let need = if out.is_empty() {
            word.chars().count()
        } else {
            out.chars().count() + 1 + word.chars().count()
        };
        if need > room {
            break;
        }
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(word);
    }
    if out.is_empty() {
        // One pathological long token — hard clip it.
        out = s.chars().take(room).collect();
    }
    out.push('…');
    out
}

/// Hard character clip with no ellipsis, for prompt context trimming. Pure.
fn clip_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        s.chars().take(max).collect()
    }
}

/// Build a dedicated lightweight backend for summarization, or `None` when no
/// Claude credential is resolvable (an offline / non-Claude run simply skips
/// summaries — the surfaces fall back to the task brief as before).
///
/// A SEPARATE backend rather than `set_model` on the worker's own: mutating the
/// live coordinator backend mid-run to a weaker model, even briefly, risks a
/// concurrent turn landing on the wrong tier.
pub fn lightweight_backend(session: &Session) -> Option<Backend> {
    let cred = crate::backend::claude::Credential::resolve(&session.env).ok()?;
    Backend::new_claude(SUMMARY_MODEL.to_string(), cred).ok()
}

/// Summarize a worker's current activity into one status-line-sized string.
///
/// Issues a SINGLE tool-less [`Backend::complete`] call at the live
/// [`current_budget`]. Best-effort by design: any error, refusal, or unusable
/// reply yields `None` and the caller leaves the previous summary in place —
/// a summarizer hiccup must never fail or stall the worker's real work.
pub async fn summarize(backend: &Backend, task: &str, recent: Option<&str>) -> Option<String> {
    let budget = current_budget();
    let system = summarizer_system(budget);
    let prompt = build_prompt(task, recent, budget);
    let turn = backend
        .complete(&system, &[Msg::user(prompt)], &[])
        .await
        .ok()?;
    sanitize(&turn.text, budget)
}

// ── Worker title ───────────────────────────────────────────────────────────
//
// The HEAD row of an escalation banner names WHICH worker this is:
// `🚀 w_f9GUaOAU · <title>`. That `<title>` used to be the raw task brief
// hard-clipped at a character count, so the banner read:
//
//   🚀 w_f9GUaOAU · Review the Atum board cards currently in column col_rev…
//
// — half the row spent re-reading the opening of a brief the operator WROTE,
// cut off one token before the only part that identifies it (the board id).
//
// A title is a DIFFERENT job from the status row beneath it. The status row
// answers "what is it doing right now" and is expected to change on every
// refresh; the title answers "which assignment is this" and must stay STABLE
// for the worker's whole life, because it is the handle the operator tracks it
// by across `:workers`, the Shift-Tab rotation, and the tray. So it is written
// ONCE, from the task brief alone, at worker start — same cheap model, same
// budget discipline as [`summarize`] — and never refreshed: a title that
// rewrites itself mid-run is a worse title.

/// Floor for the title budget. Below this a title cannot carry a subject plus
/// its target, so a very narrow terminal clips at the render site instead of
/// degrading the title itself into a bare noun.
pub const TITLE_MIN_BUDGET: usize = 20;

/// Ceiling for the title budget.
///
/// Held just under `escalation::TASK_HINT_MAX` (56) so a stored title always
/// survives the banner's own defensive clip INTACT — a model-written title the
/// renderer then has to ellipsize is exactly the failure this replaces.
pub const TITLE_MAX_BUDGET: usize = 52;

/// The character allowance for a worker title at `term_width`, derived from the
/// escalation head row's real chrome and clamped to
/// [`TITLE_MIN_BUDGET`]`..=`[`TITLE_MAX_BUDGET`]. Pure.
///
/// Only the head row is considered: unlike an activity summary (one string
/// shared by three surfaces, hence the `min` in [`budget`]), the title's
/// width-critical consumer is the banner head, and `:workers` renders it in a
/// column that is strictly wider.
pub fn title_budget(term_width: usize) -> usize {
    term_width
        .saturating_sub(ESCALATION_HEAD_CHROME)
        .clamp(TITLE_MIN_BUDGET, TITLE_MAX_BUDGET)
}

/// [`title_budget`] at the live terminal width.
pub fn current_title_budget() -> usize {
    title_budget(crate::md::term_width())
}

/// The title writer's system prompt, budget-interpolated so the hard limit the
/// model is told matches the limit [`sanitize_title`] enforces. Pure.
///
/// Deliberately asks for a NOUN PHRASE, not the verb-led fragment
/// [`summarizer_system`] asks for: the two rows of a banner sit one above the
/// other, and two verb-led lines read as one garbled sentence.
pub fn title_system(budget: usize) -> String {
    format!(
        "You write a SHORT TITLE naming a background agent worker's assignment, like a tab \
label. It renders in a terminal row next to the worker's id, so it must fit.\n\n\
Rules:\n\
- Output ONLY the title. No prose, no preamble, no quotes, no markdown, no code fences, \
no bullet, no trailing period.\n\
- HARD LIMIT: {budget} characters. Shorter is better — aim for {aim}.\n\
- A noun phrase, not a sentence and not a command: \"col_review board audit\", \
\"aish worker titles\", \"CI fix on feat/retry\".\n\
- Keep the IDENTIFYING tokens — repo, branch, PR, card, board id, file, module. Those are \
what the operator scans for; drop ordinary words before dropping an identifier.\n\
- Name the WHOLE assignment, not the first step and not the current step.\n\
- No filler. Never \"task to\", \"request to\", \"working on\", \"the agent\", \"please\".\n\
- Do not start with a verb in the imperative (\"Review …\", \"Fix …\") — name the thing \
(\"review of …\", \"CI fix …\").",
        aim = budget.saturating_sub(budget / 4).max(TITLE_MIN_BUDGET),
    )
}

/// Assemble the title writer's user message from the task brief. Pure +
/// deterministic so the prompt shape is unit-testable.
pub fn build_title_prompt(task: &str, budget: usize) -> String {
    let mut p = String::with_capacity(TASK_CONTEXT_MAX + 160);
    p.push_str("ASSIGNMENT:\n");
    p.push_str(&clip_chars(task.trim(), TASK_CONTEXT_MAX));
    p.push_str(&format!(
        "\n\nTitle naming this assignment (max {budget} chars):"
    ));
    p
}

/// Turn the model's raw reply into one clean title within `budget`, or `None`
/// when it returned nothing usable. Pure.
///
/// Delegates the shared cleanup (fences, bullets, quotes, whitespace, trailing
/// period, word-boundary clip) to [`sanitize`], then applies the two
/// title-specific strips: a `Title:` label the model may prepend, and a
/// trailing colon left over from one. Also rejects the summarizer's
/// [`STARTUP_FALLBACK`] sentinel — "starting up" is a fine STATUS but a useless
/// title, and the caller falling back to the clipped brief beats it.
pub fn sanitize_title(raw: &str, budget: usize) -> Option<String> {
    let stripped = raw
        .trim_start()
        .strip_prefix("Title:")
        .or_else(|| raw.trim_start().strip_prefix("TITLE:"))
        .unwrap_or(raw);
    let mut s = sanitize(stripped, budget)?;
    if let Some(rest) = s.strip_suffix(':') {
        s = rest.trim_end().to_string();
    }
    if s.is_empty() || s.eq_ignore_ascii_case(STARTUP_FALLBACK) {
        return None;
    }
    Some(s)
}

/// Write a worker's stable title from its task brief.
///
/// Issues a SINGLE tool-less [`Backend::complete`] call at the live
/// [`current_title_budget`]. Best-effort by design, exactly like [`summarize`]:
/// any error, refusal, or unusable reply yields `None` and every surface keeps
/// clipping the raw brief as it did before — a title writer hiccup must never
/// fail or stall the worker's real work.
pub async fn summarize_title(backend: &Backend, task: &str) -> Option<String> {
    let budget = current_title_budget();
    let system = title_system(budget);
    let prompt = build_title_prompt(task, budget);
    let turn = backend
        .complete(&system, &[Msg::user(prompt)], &[])
        .await
        .ok()?;
    sanitize_title(&turn.text, budget)
}

// ── Mid-round tracker ───────────────────────────────────────────────────────
//
// See the "Why mid-round is the load-bearing one" note at the top of the module:
// rounds are long and there is usually only ONE, so a round-boundary-only
// refresh leaves the row frozen at the startup summary for the worker's entire
// visible life. This tracker refreshes from the tool-call stream instead.

/// Minimum wall-clock spacing between mid-round refreshes. A refresh is now
/// pure string formatting plus one small `UPDATE` on the run row (see
/// [`midround_summary`]), so this is no longer a cost knob — it is a write-rate
/// knob, kept well below the ~2s poll of the consuming surfaces so the row
/// always looks live while the hot loop stays free of per-call I/O.
pub const MIDROUND_INTERVAL: std::time::Duration = std::time::Duration::from_secs(5);

/// Minimum NEW tool calls since the last refresh before another is allowed.
/// `1` is the floor that still matters: it makes the degenerate round that sits
/// in ONE very long tool call (a 20-minute `cargo build`) a no-op instead of
/// rewriting the identical row every interval.
pub const MIDROUND_MIN_CALLS: usize = 1;

/// Whether a mid-round refresh is due. Pure, so the throttle is unit-testable
/// without a clock or a backend.
pub fn should_refresh(since_last: std::time::Duration, new_calls: usize) -> bool {
    new_calls >= MIDROUND_MIN_CALLS && since_last >= MIDROUND_INTERVAL
}

/// Strip the leading display glyph (`🛠️ `/`🔧 `/`🤝 `) off an `engine` tool
/// description, leaving the text a language model should actually read. Pure.
///
/// Drops leading characters until the first printable ASCII one, so it degrades
/// safely if the glyph set ever changes and keeps a leading `./` or `../` on a
/// path; a desc with no glyph is untouched.
pub fn strip_glyph(desc: &str) -> &str {
    match desc.find(|c: char| c.is_ascii_graphic()) {
        Some(i) => &desc[i..],
        None => desc.trim(),
    }
}

/// Present-tense activity participle + the prefix `engine::describe_call`
/// puts in front of the target, per first-party tool. `None` for anything not
/// in the table (an MCP tool, a plugin tool), which falls back to the tool's
/// own name. Pure.
///
/// The prefix is stripped so the phrase reads `reading src/lib.rs` rather than
/// `reading read src/lib.rs`.
fn participle(tool: &str) -> Option<(&'static str, &'static str)> {
    Some(match tool {
        "read_file" => ("reading", "read "),
        "write_file" => ("writing", "write "),
        "edit_file" => ("editing", "edit "),
        "append_file" => ("appending to", "append "),
        "copy_file" => ("copying", "copy "),
        "rename_file" => ("moving", "rename "),
        "list_dir" => ("listing", "list "),
        "glob_expand" => ("globbing", "glob "),
        "grep_files" => ("searching", "grep "),
        "stat_file" => ("inspecting", "stat "),
        "diff_files" => ("diffing", "diff "),
        "change_dir" => ("entering", "cd "),
        "run_program" | "run_interactive" => ("running", ""),
        "remember" => ("saving a memory", ""),
        "recall" => ("recalling memory", ""),
        "run_in_background" => ("dispatching a worker", ""),
        "job_output" => ("checking a job", ""),
        "background_status" => ("checking background jobs", ""),
        "get_skill" => ("reading a skill", ""),
        "set_alert" => ("arming an alert", ""),
        "message_console" => ("messaging the operator", ""),
        "reasoning_note" => ("logging a reasoning note", ""),
        "tell" => ("steering a worker", ""),
        "stop" => ("stopping a worker", ""),
        _ => return None,
    })
}

/// An unknown tool's readable name: the last segment of an MCP tool id
/// (`mcp__atum__atum_list_sprints` → `atum_list_sprints`), falling back to the
/// description when the name is empty. Pure.
fn tool_label(tool: &str, desc: &str) -> String {
    let name = if tool.trim().is_empty() { desc } else { tool };
    name.rsplit("__").next().unwrap_or(name).trim().to_string()
}

/// Turn ONE completed tool call into a present-tense activity phrase —
/// the deterministic replacement for a per-refresh model call. Pure.
///
/// `tool` is the tool NAME and `desc` is `engine::describe_call`'s display
/// description, whose shape is tool-specific: a verb-prefixed target for the
/// file tools (`read src/lib.rs`), the bare argv for `run_program`
/// (`cargo test --lib`), the tool name for an MCP tool. The leading glyph and
/// any trailing parenthesized detail are dropped — both cost budget and add
/// nothing at a glance.
pub fn phrase(tool: &str, desc: &str) -> String {
    let text = strip_glyph(desc).trim();
    let Some((verb, prefix)) = participle(tool) else {
        return format!("calling {}", tool_label(tool, text));
    };
    // Drop the tool's verb prefix (`read `), tolerating a description that is
    // JUST the bare verb (`read`) — the target is then empty, not "read". Only
    // a prefix followed by end-of-string or whitespace counts, so a target that
    // merely starts with the same letters (`readme.md`) is left intact.
    let target = match text.strip_prefix(prefix.trim_end()) {
        Some(rest) if !prefix.is_empty() && (rest.is_empty() || rest.starts_with(' ')) => rest,
        _ => text,
    }
    .trim();
    let target = target
        .split_once(" (")
        .map_or(target, |(head, _)| head)
        .trim();
    if target.is_empty() {
        verb.to_string()
    } else {
        format!("{verb} {target}")
    }
}

/// Render the mid-round summary from the newest tool call. Pure, deterministic,
/// and already clipped to [`MAX_BUDGET`] so the durable row is status-line
/// sized at the width the widest consuming surface allows.
///
/// Shape: `reading src/engine.rs · round 1 · 17 calls` — the phrase answers
/// "what is it doing?", the tail answers "is it making progress?". A failed
/// call is marked so a stuck worker reads as stuck rather than busy.
pub fn midround_summary(phrase: &str, failed: bool, round: u64, total_calls: usize) -> String {
    let head = if failed {
        format!("failed: {phrase}")
    } else {
        phrase.to_string()
    };
    let tail = format!(" · round {round} · {total_calls} calls");
    let room = MAX_BUDGET.saturating_sub(tail.chars().count());
    format!("{}{}", clip_words(head.trim(), room), tail)
}

/// Live mid-round summary refresher for a background coordinator run.
///
/// Attached to the [`Session`] by `coordinator::drive` (so it is `Some` only for
/// a headless `--coordinator` run, exactly like `turn_audit` and
/// `worker_transcript`) and driven by `engine::run_turn`, which notes every
/// completed tool call and offers a throttled refresh point.
///
/// Owns the lightweight backend and the store handle, so it is also the single
/// writer for the startup and round-boundary refreshes — one code path, one
/// client, one place where the durable row is stamped.
pub struct ActivityTracker {
    backend: Backend,
    store: crate::coordinator_store::CoordinatorStore,
    run_id: String,
    /// The durable assignment, pre-clipped for prompt grounding.
    task: String,
    /// The newest completed tool call as `(phrase, failed)` — all the
    /// mid-round summary needs, since it is rendered, not inferred.
    latest: Option<(String, bool)>,
    total_calls: usize,
    calls_since_refresh: usize,
    last_refresh: std::time::Instant,
    round: u64,
}

impl ActivityTracker {
    /// Build a tracker, or `None` when no Claude credential resolves (an
    /// offline / non-Claude run simply has no summaries and every surface falls
    /// back to the task brief, exactly as before — this is cosmetic, never
    /// load-bearing).
    pub fn attach(
        session: &Session,
        store: &crate::coordinator_store::CoordinatorStore,
        run_id: &str,
        task: &str,
    ) -> Option<Self> {
        Some(Self {
            backend: lightweight_backend(session)?,
            store: store.clone(),
            run_id: run_id.to_string(),
            task: clip_chars(task.trim(), TASK_CONTEXT_MAX),
            latest: None,
            total_calls: 0,
            calls_since_refresh: 0,
            last_refresh: std::time::Instant::now(),
            round: 1,
        })
    }

    /// Record a COMPLETED tool call. Cheap and synchronous — pure bookkeeping,
    /// no I/O, no await — so it is safe to call on every call in the hot loop.
    ///
    /// `tool` is the tool name and `desc` is `engine`'s display description
    /// (glyph included); both are folded into a present-tense phrase by
    /// [`phrase`] right here, so a refresh is later just a format.
    pub fn note_tool_call(&mut self, tool: &str, desc: &str, is_error: bool) {
        self.latest = Some((phrase(tool, desc), is_error));
        self.total_calls = self.total_calls.saturating_add(1);
        self.calls_since_refresh = self.calls_since_refresh.saturating_add(1);
    }

    /// Refresh the durable summary from the newest tool call IF the throttle
    /// allows it. Returns the new summary when one was written.
    ///
    /// Synchronous and model-free: the summary is RENDERED from the tool-call
    /// stream the tracker already sees ([`midround_summary`]), so the mid-round
    /// path costs no tokens, cannot fail, and cannot add latency to the hot
    /// loop. Only the two boundary refreshes (startup, end-of-round) still ask
    /// a model, because only they summarize prose.
    pub fn maybe_refresh(&mut self) -> Option<String> {
        if !should_refresh(self.last_refresh.elapsed(), self.calls_since_refresh) {
            return None;
        }
        self.last_refresh = std::time::Instant::now();
        self.calls_since_refresh = 0;
        let (phrase, failed) = self.latest.clone()?;
        self.write(midround_summary(
            &phrase,
            failed,
            self.round,
            self.total_calls,
        ))
    }

    /// Seed the summary from the task brief alone, before the first round runs,
    /// so the row is meaningful from the moment the worker appears.
    pub async fn refresh_startup(&mut self) -> Option<String> {
        self.last_refresh = std::time::Instant::now();
        self.calls_since_refresh = 0;
        let task = self.task.clone();
        self.write(summarize(&self.backend, &task, None).await?)
    }

    /// Refresh from a finished round's synthesis — the model's own narrative of
    /// what it just completed, the single best signal available at a boundary.
    /// Also rolls the round counter and drops the last tool call so the next
    /// round's row doesn't describe the previous round's work.
    pub async fn refresh_round(&mut self, round: u64, synthesis: &str) -> Option<String> {
        self.last_refresh = std::time::Instant::now();
        self.calls_since_refresh = 0;
        self.latest = None;
        self.round = round.saturating_add(1);
        let task = self.task.clone();
        self.write(summarize(&self.backend, &task, Some(synthesis)).await?)
    }

    /// Write the worker's stable TITLE from the task brief — called ONCE, at
    /// startup, alongside [`Self::refresh_startup`]. Returns the title when one
    /// was written.
    ///
    /// Deliberately has no throttle and no refresh counterpart: the title names
    /// the assignment, which does not change, and the operator needs it to hold
    /// still to use it as a handle (see the module's "Worker title" note).
    /// Best-effort — a failure leaves the row's title `NULL` and the surfaces
    /// fall back to clipping the brief.
    pub async fn refresh_title(&mut self) -> Option<String> {
        let task = self.task.clone();
        let title = summarize_title(&self.backend, &task).await?;
        let _ = self.store.set_title(&self.run_id, &title);
        Some(title)
    }

    /// Stamp the durable row. Best-effort — a store write error is swallowed.
    fn write(&self, sum: String) -> Option<String> {
        let _ = self.store.set_activity_summary(&self.run_id, &sum);
        Some(sum)
    }
}

// ── Parent-side read path ────────────────────────────────────────────────────
//
// A worker's summary is written by its coordinator SUBPROCESS, so the parent's
// in-memory `WorkerJob` never sees it — the durable row is the only channel. The
// consuming surfaces are PAINT paths (`:workers` render, the footer's escalation
// refresh, which repaints on every heartbeat), so a naive point lookup would put
// SQLite on the repaint path. This read-through cache bounds that to one query
// per worker per [`POLL_INTERVAL`] regardless of repaint rate.
//
// Kept here rather than as a `WorkerJob` field on purpose: it serves BOTH
// surfaces (and durable rows from other sessions, which have no `WorkerJob` at
// all) with one implementation, and it keeps a store handle out of `worker.rs`.

/// Minimum spacing between durable-store polls for the SAME run id. A summary
/// changes at most once per [`MIDROUND_INTERVAL`] (tens of seconds), so a 2s
/// floor is invisible to the operator and makes the repaint path effectively
/// free.
const POLL_INTERVAL: std::time::Duration = std::time::Duration::from_secs(2);

type SummaryCache =
    std::sync::Mutex<std::collections::HashMap<String, (std::time::Instant, Option<String>)>>;

fn cache() -> &'static SummaryCache {
    static CACHE: std::sync::OnceLock<SummaryCache> = std::sync::OnceLock::new();
    CACHE.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Titles get their OWN cache rather than sharing one keyed by a composite:
/// they have a different lifetime (written once, then immutable) and a miss
/// means something different (fall back to the clipped brief vs. "no summary
/// yet"), so keeping them separate keeps both lookups a plain `run_id` get.
fn title_cache() -> &'static SummaryCache {
    static CACHE: std::sync::OnceLock<SummaryCache> = std::sync::OnceLock::new();
    CACHE.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Read-through [`POLL_INTERVAL`] cache around one durable-store lookup.
///
/// Caches the NEGATIVE result too, on purpose: the common case on a
/// pre-migration row (or a run whose title writer failed) is a permanent
/// `None`, and without that a repaint-driven caller would re-query SQLite on
/// every frame forever.
fn poll(
    c: &'static SummaryCache,
    run_id: &str,
    fetch: impl FnOnce() -> Option<String>,
) -> Option<String> {
    let now = std::time::Instant::now();
    let mut guard = c.lock().unwrap();
    if let Some((at, val)) = guard.get(run_id)
        && now.duration_since(*at) < POLL_INTERVAL
    {
        return val.clone();
    }
    let fresh = fetch();
    guard.insert(run_id.to_string(), (now, fresh.clone()));
    fresh
}

/// The cached activity summary for `run_id`, refreshed from `store` at most once
/// per [`POLL_INTERVAL`]. `None` when the run has no summary yet (pre-migration
/// row, summarizer disabled, or the first round hasn't landed) — callers then
/// fall back to clipping the task brief.
pub fn cached_summary(
    store: &crate::coordinator_store::CoordinatorStore,
    run_id: &str,
) -> Option<String> {
    poll(cache(), run_id, || store.activity_summary(run_id))
}

/// The cached worker TITLE for `run_id`, refreshed from `store` at most once per
/// [`POLL_INTERVAL`]. `None` when the run has no title (a row written before the
/// migration, or a run whose title writer found no credential / failed) —
/// callers then fall back to clipping the task brief, which is the pre-title
/// behaviour.
pub fn cached_title(
    store: &crate::coordinator_store::CoordinatorStore,
    run_id: &str,
) -> Option<String> {
    poll(title_cache(), run_id, || store.title(run_id))
}

/// Drop a run's cached summary AND title — called when a worker is closed so a
/// long-lived session's caches can't grow without bound.
pub fn forget_cached(run_id: &str) {
    cache().lock().unwrap().remove(run_id);
    title_cache().lock().unwrap().remove(run_id);
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── Mid-round tracker ───────────────────────────────────────────────────
    //
    // The bug these cover: a coordinator does its whole job in ONE round, so a
    // round-boundary-only refresh fires once (at termination) and every surface
    // shows "starting up" for the worker's entire visible life.

    #[test]
    fn throttle_needs_both_time_and_new_calls() {
        use std::time::Duration;
        // Both conditions met -> refresh.
        assert!(should_refresh(MIDROUND_INTERVAL, MIDROUND_MIN_CALLS));
        assert!(should_refresh(Duration::from_secs(600), 40));
        // Enough calls but too soon: a burst of fast reads must not put a
        // durable row write in the hot loop per read.
        assert!(!should_refresh(
            MIDROUND_INTERVAL - Duration::from_millis(1),
            99
        ));
        // Enough time but no new work: a round parked in ONE 20-minute
        // `cargo build` must not rewrite an unchanged row every interval.
        assert!(!should_refresh(Duration::from_secs(3600), 0));
        assert!(!should_refresh(
            Duration::from_secs(3600),
            MIDROUND_MIN_CALLS - 1
        ));
        // Nothing has happened at all.
        assert!(!should_refresh(Duration::ZERO, 0));
    }

    #[test]
    fn throttle_fires_well_inside_an_observed_round() {
        // Live symptom runs: 3m07s and 5m25s, both still on round 1. At one
        // refresh per MIDROUND_INTERVAL the row moves many times over the span
        // where it previously never moved once.
        let span = std::time::Duration::from_secs(187); // 3m07s
        let refreshes = span.as_secs() / MIDROUND_INTERVAL.as_secs();
        assert!(
            refreshes >= 6,
            "expected the row to move repeatedly inside a single round, got {refreshes}"
        );
    }

    #[test]
    fn strip_glyph_drops_decoration_not_text() {
        // `engine`'s own description prefixes, which carry no meaning for a
        // language model but do eat prompt budget.
        assert_eq!(
            strip_glyph("🛠️ run_program cargo test"),
            "run_program cargo test"
        );
        assert_eq!(
            strip_glyph("🔧 read_file src/lib.rs"),
            "read_file src/lib.rs"
        );
        assert_eq!(strip_glyph("🤝 tell w_abc"), "tell w_abc");
        // Already clean -> untouched.
        assert_eq!(strip_glyph("grep_files foo"), "grep_files foo");
        // Degenerate inputs must not panic or slice mid-codepoint.
        assert_eq!(strip_glyph(""), "");
        assert_eq!(strip_glyph("🛠️"), "🛠️");
        assert_eq!(strip_glyph("  🛠️  x"), "x");
        // Leading ASCII punctuation is text, not decoration: a relative path
        // must survive intact.
        assert_eq!(
            strip_glyph("🛠️ ./scripts/build.sh --release"),
            "./scripts/build.sh --release"
        );
    }

    #[test]
    fn phrase_reads_as_present_tense_activity() {
        // File tools: `describe_call`'s own verb prefix is replaced, never
        // doubled ("reading src/lib.rs", not "reading read src/lib.rs").
        assert_eq!(
            phrase("read_file", "🔧 read src/lib.rs"),
            "reading src/lib.rs"
        );
        assert_eq!(
            phrase("write_file", "🔧 write src/new.rs"),
            "writing src/new.rs"
        );
        assert_eq!(
            phrase("grep_files", "🔧 grep note_tool_call"),
            "searching note_tool_call"
        );
        assert_eq!(phrase("list_dir", "🔧 list src"), "listing src");
        // `run_program`'s description is the bare argv — no prefix to strip.
        assert_eq!(
            phrase("run_program", "🛠️ cargo test --lib"),
            "running cargo test --lib"
        );
        // Trailing parenthesized detail is chrome at a glance: dropped.
        assert_eq!(
            phrase("edit_file", "🔧 edit src/engine.rs (\"note_tool_call\")"),
            "editing src/engine.rs"
        );
    }

    #[test]
    fn phrase_falls_back_for_an_unknown_tool() {
        // MCP tools are not in the table and must still read as an activity,
        // with the server prefix dropped.
        assert_eq!(
            phrase(
                "mcp__atum__atum_list_sprints",
                "🛠️ mcp__atum__atum_list_sprints"
            ),
            "calling atum_list_sprints"
        );
        assert_eq!(
            phrase("some_plugin_tool", "🛠️ whatever"),
            "calling some_plugin_tool"
        );
        // Degenerate inputs must not panic.
        assert_eq!(phrase("", ""), "calling ");
        assert_eq!(phrase("read_file", "🔧 read "), "reading");
    }

    #[test]
    fn midround_summary_carries_activity_and_progress() {
        let s = midround_summary("reading src/engine.rs", false, 1, 17);
        // What it's doing, and that it's still moving.
        assert!(s.starts_with("reading src/engine.rs"), "{s}");
        assert!(s.contains("round 1"), "{s}");
        assert!(s.contains("17 calls"), "{s}");
        // A failure must read as stuck, not busy.
        let f = midround_summary("running cargo build", true, 3, 44);
        assert!(f.starts_with("failed: running cargo build"), "{f}");
        assert!(f.contains("round 3"), "{f}");
    }

    #[test]
    fn midround_summary_fits_the_narrowest_surface() {
        // The stored row is consumed by surfaces that clip at `budget(width)`;
        // rendering already inside MAX_BUDGET means the progress tail is never
        // the part that gets truncated away.
        let long = "running ".to_string() + &"cargo test --package aish-very-long-name ".repeat(6);
        let s = midround_summary(&long, true, 12, 999);
        assert!(
            s.chars().count() <= MAX_BUDGET,
            "{} chars: {s}",
            s.chars().count()
        );
        assert!(s.ends_with("· round 12 · 999 calls"), "{s}");
        assert!(
            s.contains('…'),
            "expected the phrase, not the tail, to be clipped: {s}"
        );
    }

    #[test]
    fn budget_is_derived_from_the_narrowest_surface() {
        // The `:workers` row carries the most chrome, so it binds.
        // 118 - 46 = 72, which is inside the clamp window.
        assert_eq!(budget(118), 72);
        // The other two surfaces would have allowed more.
        const { assert!(118 - ESCALATION_HEAD_CHROME > 72) };
        const { assert!(118 - ESCALATION_STATUS_CHROME > 72) };
    }

    #[test]
    fn budget_at_the_measured_tui_width_is_the_ceiling() {
        // 155 cols (the width this was tuned against): min(109,129,138) = 109,
        // clamped to MAX_BUDGET so a wide terminal doesn't buy prose.
        assert_eq!(budget(155), MAX_BUDGET);
    }

    #[test]
    fn budget_clamps_both_ends() {
        // Classic 80-column terminal: 80 - 46 = 34, inside the window.
        assert_eq!(budget(80), 34);
        // Very narrow / degenerate widths floor at MIN_BUDGET.
        assert_eq!(budget(60), MIN_BUDGET);
        assert_eq!(budget(10), MIN_BUDGET);
        assert_eq!(budget(0), MIN_BUDGET);
        // Piped output reports usize::MAX — must saturate, not overflow.
        assert_eq!(budget(usize::MAX), MAX_BUDGET);
    }

    #[test]
    fn budget_is_monotonic_in_width() {
        let mut prev = 0;
        for w in [0usize, 40, 70, 80, 100, 126, 155, 300] {
            let b = budget(w);
            assert!(b >= prev, "budget({w}) = {b} regressed below {prev}");
            assert!((MIN_BUDGET..=MAX_BUDGET).contains(&b));
            prev = b;
        }
    }

    #[test]
    fn sanitize_takes_one_clean_line() {
        assert_eq!(
            sanitize("wiring summaries into :workers", 80).as_deref(),
            Some("wiring summaries into :workers")
        );
        // whitespace collapsed, first meaningful line wins
        assert_eq!(
            sanitize("  \n\n  fixing   CI on feat/foo  \nstray trailing note", 80).as_deref(),
            Some("fixing CI on feat/foo")
        );
    }

    #[test]
    fn sanitize_strips_fences_bullets_quotes_and_trailing_period() {
        assert_eq!(
            sanitize("```\nauditing 12 merged cards\n```", 80).as_deref(),
            Some("auditing 12 merged cards")
        );
        assert_eq!(
            sanitize("- rebasing feat/bar", 80).as_deref(),
            Some("rebasing feat/bar")
        );
        assert_eq!(
            sanitize("\"opening draft PR\"", 80).as_deref(),
            Some("opening draft PR")
        );
        assert_eq!(
            sanitize("running cargo test.", 80).as_deref(),
            Some("running cargo test")
        );
        // an ellipsis-ish trailing run is left alone
        assert_eq!(
            sanitize("still building..", 80).as_deref(),
            Some("still building..")
        );
    }

    #[test]
    fn sanitize_returns_none_for_nothing_usable() {
        assert_eq!(sanitize("", 80), None);
        assert_eq!(sanitize("   \n\t  ", 80), None);
        assert_eq!(sanitize("```\n```", 80), None);
        assert_eq!(sanitize("\"\"", 80), None);
    }

    #[test]
    fn sanitize_never_exceeds_the_budget() {
        let long = "wiring the lightweight activity summarizer into the coordinator round \
boundary and both status surfaces";
        for b in [MIN_BUDGET, 34, 50, MAX_BUDGET] {
            let got = sanitize(long, b).expect("summary");
            assert!(
                got.chars().count() <= b,
                "budget {b}: {:?} is {} chars",
                got,
                got.chars().count()
            );
        }
    }

    #[test]
    fn clip_words_breaks_on_word_boundaries() {
        let s = "fixing CI on feat/activity-summary";
        // Fits — untouched, no ellipsis.
        assert_eq!(clip_words(s, 80), s);
        // Clipped on a word boundary with an ellipsis.
        let got = clip_words(s, 16);
        assert!(got.ends_with('…'), "{got:?}");
        assert!(!got.contains("feat/activity-summary"), "{got:?}");
        assert!(got.chars().count() <= 16);
    }

    #[test]
    fn clip_words_handles_one_overlong_token() {
        let got = clip_words("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", 10);
        assert_eq!(got.chars().count(), 10);
        assert!(got.ends_with('…'));
    }

    #[test]
    fn clip_words_is_char_safe_on_multibyte() {
        // Must not panic slicing inside a multi-byte scalar.
        let got = clip_words("résumé des tâches en cours sur la branche", 12);
        assert!(got.chars().count() <= 12, "{got:?}");
    }

    #[test]
    fn summarizer_system_states_the_budget_it_is_held_to() {
        let s = summarizer_system(34);
        assert!(s.contains("HARD LIMIT: 34 characters"), "{s}");
        assert!(s.contains(STARTUP_FALLBACK), "{s}");
    }

    #[test]
    fn build_prompt_distinguishes_startup_from_a_completed_round() {
        let start = build_prompt("Do the big thing", None, 80);
        assert!(start.contains("just starting"), "{start}");
        assert!(start.contains("Do the big thing"), "{start}");
        assert!(start.contains("max 80 chars"), "{start}");

        let mid = build_prompt("Do the big thing", Some("Added the store column."), 80);
        assert!(mid.contains("MOST RECENT TURN"), "{mid}");
        assert!(mid.contains("Added the store column."), "{mid}");
        assert!(!mid.contains("just starting"), "{mid}");
    }

    #[test]
    fn build_prompt_clips_oversized_context() {
        let huge_task = "t".repeat(5_000);
        let huge_recent = "r".repeat(5_000);
        let p = build_prompt(&huge_task, Some(&huge_recent), 80);
        assert!(
            p.len() < TASK_CONTEXT_MAX + RECENT_CONTEXT_MAX + 512,
            "{}",
            p.len()
        );
    }

    // ── Titles ──────────────────────────────────────────────────────────────
    //
    // The bug these cover: the banner head row showed a mid-word clip of the
    // raw brief ("Review the Atum board cards currently in column col_rev…"),
    // so the operator could not tell two workers apart at a glance.

    #[test]
    fn title_budget_is_clamped_at_both_ends() {
        // A narrow terminal can't go below the floor...
        assert_eq!(title_budget(0), TITLE_MIN_BUDGET);
        assert_eq!(title_budget(20), TITLE_MIN_BUDGET);
        // ...and a wide one can't exceed the escalation banner's own clip.
        assert_eq!(title_budget(400), TITLE_MAX_BUDGET);
        // In between it tracks the real chrome.
        let w = 50;
        assert_eq!(title_budget(w), w - ESCALATION_HEAD_CHROME);
    }

    #[test]
    fn title_budget_never_exceeds_the_banner_clip() {
        // Whatever the width, a stored title must survive the escalation
        // banner's defensive clip intact — otherwise we re-introduce the
        // ellipsis we set out to remove.
        for w in [0usize, 1, 40, 66, 80, 120, 200, 1000] {
            let b = title_budget(w);
            assert!(b <= crate::escalation::TASK_HINT_MAX, "width {w} -> {b}");
            assert!(b <= TITLE_MAX_BUDGET, "width {w} -> {b}");
            assert!(b >= TITLE_MIN_BUDGET, "width {w} -> {b}");
        }
    }

    #[test]
    fn sanitize_title_strips_a_label_and_trailing_punctuation() {
        assert_eq!(
            sanitize_title("Title: col_review board audit", 52).as_deref(),
            Some("col_review board audit")
        );
        assert_eq!(
            sanitize_title("TITLE: aish worker titles", 52).as_deref(),
            Some("aish worker titles")
        );
        assert_eq!(
            sanitize_title("aish worker titles.", 52).as_deref(),
            Some("aish worker titles")
        );
        assert_eq!(
            sanitize_title("\"aish worker titles\"", 52).as_deref(),
            Some("aish worker titles")
        );
        // A colon left over from a label the model half-dropped.
        assert_eq!(
            sanitize_title("col_review board audit:", 52).as_deref(),
            Some("col_review board audit")
        );
    }

    #[test]
    fn sanitize_title_rejects_junk_and_the_startup_sentinel() {
        assert_eq!(sanitize_title("", 52), None);
        assert_eq!(sanitize_title("   \n ", 52), None);
        // "starting up" is a fine STATUS but a useless TITLE — the caller's
        // clipped-brief fallback beats it.
        assert_eq!(sanitize_title(STARTUP_FALLBACK, 52), None);
        assert_eq!(sanitize_title("Starting Up", 52), None);
    }

    #[test]
    fn sanitize_title_honours_the_budget() {
        let long = "a review of every Atum board card currently parked in col_review for b_ed1a";
        for budget in [TITLE_MIN_BUDGET, 30, TITLE_MAX_BUDGET] {
            let t = sanitize_title(long, budget).expect("non-empty");
            assert!(
                t.chars().count() <= budget,
                "budget {budget} -> {:?} ({} chars)",
                t,
                t.chars().count()
            );
        }
    }

    #[test]
    fn title_system_states_the_budget_it_is_held_to() {
        let s = title_system(40);
        assert!(s.contains("HARD LIMIT: 40 characters"), "{s}");
        // Noun-phrase instruction is the whole point of a separate prompt:
        // two verb-led rows stacked read as one garbled sentence.
        assert!(s.contains("noun phrase"), "{s}");
    }

    #[test]
    fn build_title_prompt_carries_the_brief_and_the_limit() {
        let p = build_title_prompt("  Review the Atum board cards in col_review  ", 44);
        assert!(p.contains("ASSIGNMENT:"), "{p}");
        assert!(
            p.contains("Review the Atum board cards in col_review"),
            "{p}"
        );
        assert!(p.contains("max 44 chars"), "{p}");

        // Oversized briefs are clipped, not passed whole to the model.
        let huge = build_title_prompt(&"t".repeat(5_000), 44);
        assert!(huge.len() < TASK_CONTEXT_MAX + 512, "{}", huge.len());
    }
}
